def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]

    def sections(size, separators):
        result = []
        start = 0
        for s in separators:
            result.append((start, s))
            start = s + 1
        result.append((start, size))
        return result

    row_sections = sections(h, sep_rows)
    col_sections = sections(w, sep_cols)
    background = grid[0][0]
    output = []

    for r0, r1 in row_sections:
        row = []
        for c0, c1 in col_sections:
            count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if count == 2 else background)
        output.append(row)

    return output
